mapper.select:
select
id, subject_name, subject_difficult, settle_name, subject_type, subject_score, subject_parse, created_by,
created_time, update_by, update_time, is_deleted, read_count
from subject_info


        and id = #{subjectInfo.id}


        and subject_name = #{subjectInfo.subjectName}


        and subject_difficult = #{subjectInfo.subjectDifficult}


        and settle_name = #{subjectInfo.settleName}


        and subject_type = #{subjectInfo.subjectType}


        and subject_score = #{subjectInfo.subjectScore}


        and subject_parse = #{subjectInfo.subjectParse}


        and created_by = #{subjectInfo.createdBy}


        and created_time = #{subjectInfo.createdTime}


        and update_by = #{subjectInfo.updateBy}


        and update_time = #{subjectInfo.updateTime}


        and is_deleted = #{subjectInfo.isDeleted}



    limit #{offset}, #{pageSize}

select count(1)
from subject_info


        and id = #{id}


        and subject_name = #{subjectName}


        and subject_difficult = #{subjectDifficult}


        and settle_name = #{settleName}


        and subject_type = #{subjectType}


        and subject_score = #{subjectScore}


        and subject_parse = #{subjectParse}


        and created_by = #{createdBy}


        and created_time = #{createdTime}


        and update_by = #{updateBy}


        and update_time = #{updateTime}


        and is_deleted = #{isDeleted}

select count(distinct a.id)
from subject_info a

join subject_mapping b on a.id = b.subject_id and b.is_deleted = 0

where a.is_deleted = 0

    and (b.category_id = #{categoryId} or b.category_id in (select id from subject_category where parent_id = #{categoryId}))


    and b.label_id = #{labelId}


    and a.subject_difficult = #{subjectInfo.subjectDifficult}


    and a.subject_type = #{subjectInfo.subjectType}

select distinct a.id, a.subject_name, a.subject_difficult, a.settle_name, a.subject_type, a.subject_score, a.subject_parse, a.created_by, a.created_time, a.update_by, a.update_time, a.is_deleted, a.read_count from subject_info a
join subject_mapping b on a.id = b.subject_id and b.is_deleted = 0
where a.is_deleted = 0
and (b.category_id = #{categoryId} or b.category_id in (select id from subject_category where parent_id = #{categoryId}))
and b.label_id = #{labelId}
and a.subject_difficult = #{subjectInfo.subjectDifficult}
and a.subject_type = #{subjectInfo.subjectType}
order by a.read_count desc, a.id desc
order by a.created_time desc, a.id desc
limit #{start},#{pageSize}

select count(distinct a.id) from subject_info a left join subject_brief b on a.id = b.subject_id and b.is_deleted = 0 where a.is_deleted = 0
and a.subject_type = #{subjectType}
and ( a.subject_name like concat('%', #{keyWord}, '%') or a.subject_parse like concat('%', #{keyWord}, '%') or b.subject_answer like concat('%', #{keyWord}, '%') )

select distinct a.id, a.subject_name, a.subject_difficult, a.settle_name, a.subject_type, a.subject_score, a.subject_parse, a.created_by, a.created_time, a.update_by, a.update_time, a.is_deleted, a.read_count from subject_info a left join subject_brief b on a.id = b.subject_id and b.is_deleted = 0 where a.is_deleted = 0
and a.subject_type = #{subjectType}
and ( a.subject_name like concat('%', #{keyWord}, '%') or a.subject_parse like concat('%', #{keyWord}, '%') or b.subject_answer like concat('%', #{keyWord}, '%') )
order by case when a.subject_name like concat('%', #{keyWord}, '%') then 1 else 2 end, a.id desc limit #{start},#{pageSize}

select a.id
from subject_info a,
     subject_mapping b
where a.id = b.subject_id
and b.category_id = #{categoryId}
and b.label_id = #{labelId}

    and a.id > #{subjectId}


    and a.id < #{subjectId}

limit 0,1
